<?php
if(!defined('ABSPATH'))exit;
add_action('init',function(){if(get_option('bhc_catalog_quality_audit_batch_v236'))return;$ids=get_posts(['post_type'=>'product','post_status'=>['publish','draft'],'numberposts'=>-1,'fields'=>'ids']);$out=[];foreach($ids as $id){if(get_post_meta($id,'_bhc_catalog_quality_state',true)!=='reference_needs_verification')continue;$type=get_post_meta($id,'_bhc_source_type',true);$spec=get_post_meta($id,'_bhc_structured_specs',true);$img=get_post_meta($id,'_bhc_image_status',true);if(in_array($type,['exact_model_page','exact_retailer_page','official_exact_model_page'],true)&&strlen($spec)>1000&&$img==='generated_4k_transparent'){update_post_meta($id,'_bhc_verification_status','verified_reference');update_post_meta($id,'_bhc_catalog_quality_state','reference_verified');update_post_meta($id,'_bhc_source_checked_at','2026-11-20');update_post_meta($id,'_bhc_source_evidence',get_post_meta($id,'_bhc_source_evidence',true).' | ممیزی دسته‌ای فاز ۲۳۶: نوع منبع مدل دقیق، حجم مشخصات بیش از ۱۰۰۰ کاراکتر و تصویر اختصاصی 4K شفاف کنترل شد.');$out[$id]=get_post_meta($id,'_bhc_model',true);}}update_option('bhc_catalog_quality_audit_batch_v236',['at'=>current_time('mysql'),'count'=>count($out),'items'=>$out],false);},236);
